ac-3_smt", "ac-3.9_smt", "ac-3.3_smt", "ac-3.3_smt.b.2", "ac-3.3_smt.b.1", "ac-3.3_smt.c", "ac-3.3_smt.a", "ac-3.3_smt.b.3", "ac-3.3_smt.b.4", "ac-3.3_smt.b.5", "ac-3.3_smt.b", "ac-3.4_smt", "ac-3.4_smt.b", "ac-3.4_smt.a", "ac-3.4_smt.e", "ac-3.11_smt", "ac-3_gdn", "ac-3.9_gdn", "ac-3.3_gdn", "ac-3.4_gdn", "ac-3.11_gdn"]}, "fallback_used": false, "hierarchy_closure_used": false, "per_identifier_provenance": [{"source": "frozen_window", "source_id": "ac-3_smt"}, {"source": "frozen_window", "source_id": "ac-3.9_smt"}, {"source": "frozen_window", "source_id": "ac-3.3_smt"}, {"source": "frozen_window", "source_id": "ac-3.3_smt.b.2"}, {"source": "frozen_window", "source_id": "ac-3.3_smt.b.1"}, {"source": "frozen_window", "source_id": "ac-3.3_smt.c"}, {"source": "frozen_window", "source_id": "ac-3.3_smt.a"}, {"source": "frozen_window", "source_id": "ac-3.3_smt.b.3"}, {"source": "frozen_window", "source_id": "ac-3.3_smt.b.4"}, {"source": "frozen_window", "source_id": "ac-3.3_smt.b.5"}, {"source": "frozen_window", "source_id": "ac-3.3_smt.b"}, {"source": "frozen_window", "source_id": "ac-3.4_smt"}, {"source": "frozen_window", "source_id": "ac-3.4_smt.b"}, {"source": "frozen_window", "source_id": "ac-3.4_smt.a"}, {"source": "frozen_window", "source_id": "ac-3.4_smt.e"}, {"source": "frozen_window", "source_id": "ac-3.11_smt"}, {"source": "frozen_window", "source_id": "ac-3_gdn"}, {"source": "frozen_window", "source_id": "ac-3.9_gdn"}, {"source": "frozen_window", "source_id": "ac-3.3_gdn"}, {"source": "frozen_window", "source_id": "ac-3.4_gdn"}, {"source": "frozen_window", "source_id": "ac-3.11_gdn"}], "prepared_context_sha256": "564e2e686c8e2aedbea1c08761d7b80cb05274120adde79b73acedff1f6bf846", "rescue_used": false, "result_id": "rq2_no_selector_v1", "selector_called": false, "selector_policy": "bypassed_retain_entire_frozen_window"}, "evidence_spans": [{"source_id": "ac-3_smt", "span_text": "Enforce approved authorizations for logical access to information and system resources in accordance with applicable access control policies."}, {"source_id": "ac-3.9_smt", "span_text": "Release information outside of the system only if: (a) The receiving {{ insert: param, ac-03.09_odp.01 }} provides {{ insert: param, ac-03.09_odp.02 }} ; and (b) {{ insert: param, ac-03.09_odp.03 }} are used to validate the appropriateness of the information designated for release."}, {"source_id": "ac-3.3_smt", "span_text": "Enforce {{ insert: param, ac-3.3_prm_1 }} over the set of covered subjects and objects specified in the policy, and where the policy: (a) Is uniformly enforced across the covered subjects and objects within the system; (b) Specifies that a subject that has been granted access to information is constrained from doing any of the following; (1) Passing the information to unauthorized subjects or objects; (2) Granting its privileges to other subjects; (3) Changing one or more security attributes (specified by the policy) on subjects, objects, the system, or system components; (4) Choosing the security attributes and attribute values (specified by the policy) to be associated with newly created or modified objects; and (5) Changing the rules governing access control; and (c) Specifies that {{ insert: param, ac-03.03_odp.03 }} may explicitly be granted {{ insert: param, ac-03.03_odp.04 }} such that they are not limited by any defined subset (or all) of the above constraints."}, {"source_id": "ac-3.3_smt.b.2", "span_text": "Granting its privileges to other subjects;"}, {"source_id": "ac-3.3_smt.b.1", "span_text": "Passing the information to unauthorized subjects or objects;"}, {"source_id": "ac-3.3_smt.c", "span_text": "Specifies that {{ insert: param, ac-03.03_odp.03 }} may explicitly be granted {{ insert: param, ac-03.03_odp.04 }} such that they are not limited by any defined subset (or all) of the above constraints."}, {"source_id": "ac-3.3_smt.a", "span_text": "Is uniformly enforced across the covered subjects and objects within the system;"}, {"source_id": "ac-3.3_smt.b.3", "span_text": "Changing one or more security attributes (specified by the policy) on subjects, objects, the system, or system components;"}, {"source_id": "ac-3.3_smt.b.4", "span_text": "Choosing the security attributes and attribute values (specified by the policy) to be associated with newly created or modified objects; and"}, {"source_id": "ac-3.3_smt.b.5", "span_text": "Changing the rules governing access control; and"}, {"source_id": "ac-3.3_smt.b", "span_text": "Specifies that a subject that has been granted access to information is constrained from doing any of the following;"}, {"source_id": "ac-3.4_smt", "span_text": "Enforce {{ insert: param, ac-3.4_prm_1 }} over the set of covered subjects and objects specified in the policy, and where the policy specifies that a subject that has been granted access to information can do one or more of the following: (a) Pass the information to any other subjects or objects; (b) Grant its privileges to other subjects; (c) Change security attributes on subjects, objects, the system, or the system’s components; (d) Choose the security attributes to be associated with newly created or revised objects; or (e) Change the rules governing access control."}, {"source_id": "ac-3.4_smt.b", "span_text": "Grant its privileges to other subjects;"}, {"source_id": "ac-3.4_smt.a", "span_text": "Pass the information to any other subjects or objects;"}, {"source_id": "ac-3.4_smt.e", "span_text": "Change the rules governing access control."}, {"source_id": "ac-3.11_smt", "span_text": "Restrict access to data repositories containing {{ insert: param, ac-03.11_odp }}."}, {"source_id": "ac-3_gdn", "span_text": "Access control policies control access between active entities or subjects (i.e., users or processes acting on behalf of users) and passive entities or objects (i.e., devices, files, records, domains) in organizational systems. In addition to enforcing authorized access at the system level and recognizing that systems can host many applications and services in support of mission and business functions, access enforcement mechanisms can also be employed at the application and service level to provide increased information security and privacy. In contrast to logical access controls that are implemented within the system, physical access controls are addressed by the controls in the Physical and Environmental Protection ( [PE](#pe) ) family."}, {"source_id": "ac-3.9_gdn", "span_text": "Organizations can only directly protect information when it resides within the system. Additional controls may be needed to ensure that organizational information is adequately protected once it is transmitted outside of the system. In situations where the system is unable to determine the adequacy of the protections provided by external entities, as a mitigation measure, organizations procedurally determine whether the external systems are providing adequate controls. The means used to determine the adequacy of controls provided by external systems include conducting periodic assessments (inspections/tests), establishing agreements between the organization and its counterpart organizations, or some other process. The means used by external entities to protect the information received need not be the same as those used by the organization, but the means employed are sufficient to provide consistent adjudication of the security and privacy policy to protect the information and individuals’ privacy.

Controlled release of information requires systems to implement technical or procedural means to validate the information prior to releasing it to external systems. For example, if the system passes information to a system controlled by another organization, technical means are employed to validate that the security and privacy attributes associated with the exported information are appropriate for the receiving system. Alternatively, if the system passes information to a printer in organization-controlled space, procedural means can be employed to ensure that only authorized individuals gain access to the printer."}, {"source_id": "ac-3.3_gdn", "span_text": "Mandatory access control is a type of nondiscretionary access control. Mandatory access control policies constrain what actions subjects can take with information obtained from objects for which they have already been granted access. This prevents the subjects from passing the information to unauthorized subjects and objects. Mandatory access control policies constrain actions that subjects can take with respect to the propagation of access control privileges; that is, a subject with a privilege cannot pass that privilege to other subjects. The policy is uniformly enforced over all subjects and objects to which the system has control. Otherwise, the access control policy can be circumvented. This enforcement is provided by an implementation that meets the reference monitor concept as described in [AC-25](#ac-25) . The policy is bounded by the system (i.e., once the information is passed outside of the control of the system, additional means may be required to ensure that the constraints on the information remain in effect).

The trusted subjects described above are granted privileges consistent with the concept of least privilege (see [AC-6](#ac-6) ). Trusted subjects are only given the minimum privileges necessary for satisfying organizational mission/business needs relative to the above policy. The control is most applicable when there is a mandate that establishes a policy regarding access to controlled unclassified information or classified information and some users of the system are not authorized access to all such information resident in the system. Mandatory access control can operate in conjunction with discretionary access control as described in [AC-3(4)](#ac-3.4) . A subject constrained in its operation by mandatory access control policies can still operate under the less rigorous constraints of AC-3(4), but mandatory access control policies take precedence over the less rigorous constraints of AC-3(4). For example, while a mandatory access control policy imposes a constraint that prevents a subject from passing information to another subject operating at a different impact or classification level, AC-3(4) permits the subject to pass the information to any other subject with the same impact or classification level as the subject. Examples of mandatory access control policies include the Bell-LaPadula policy to protect confidentiality of information and the Biba policy to protect the integrity of information."}, {"source_id": "ac-3.4_gdn", "span_text": "When discretionary access control policies are implemented, subjects are not constrained with regard to what actions they can take with information for which they have already been granted access. Thus, subjects that have been granted access to information are not prevented from passing the information to other subjects or objects (i.e., subjects have the discretion to pass). Discretionary access control can operate in conjunction with mandatory access control as described in [AC-3(3)](#ac-3.3) and [AC-3(15)](#ac-3.15) . A subject that is constrained in its operation by mandatory access control policies can still operate under the less rigorous constraints of discretionary access control. Therefore, while [AC-3(3)](#ac-3.3) imposes constraints that prevent a subject from passing information to another subject operating at a different impact or classification level, [AC-3(4)](#ac-3.4) permits the subject to pass the information to any subject at the same impact or classification level. The policy is bounded by the system. Once the information is passed outside of system control, additional means may be required to ensure that the constraints remain in effect. While traditional definitions of discretionary access control require identity-based access control, that limitation is not required for this particular use of discretionary access control."}, {"source_id": "ac-3.11_gdn", "span_text": "Restricting access to specific information is intended to provide flexibility regarding access control of specific information types within a system. For example, role-based access could be employed to allow access to only a specific type of personally identifiable information within a database rather than allowing access to the database in its entirety. Other examples include restricting access to cryptographic keys, authentication information, and selected system information."}], "framework_version": "rev5", "odp_required_list": ["ac-03.03_odp.03", "ac-03.03_odp.04", "ac-03.09_odp.01", "ac-03.09_odp.02", "ac-03.09_odp.03", "ac-03.11_odp", "ac-3.3_prm_1", "ac-3.4_prm_1"], "primary_citation": "ac-3_smt", "question": "What must an organization enforce regarding logical access to its information and systems?", "selected_source_ids": ["ac-3_smt", "ac-3.9_smt", "ac-3.3_smt", "ac-3.3_smt.b.2", "ac-3.3_smt.b.1", "ac-3.3_smt.c", "ac-3.3_smt.a", "ac-3.3_smt.b.3", "ac-3.3_smt.b.4", "ac-3.3_smt.b.5", "ac-3.3_smt.b", "ac-3.4_smt", "ac-3.4_smt.b", "ac-3.4_smt.a", "ac-3.4_smt.e", "ac-3.11_smt", "ac-3_gdn", "ac-3.9_gdn", "ac-3.3_gdn", "ac-3.4_gdn", "ac-3.11_gdn"], "status": "PARAMS_REQUIRED"}

{"all_citations": "au-11_smt, au-3_smt, au-3_smt.e, au-3_smt.f, au-3_smt.c, au-3_smt.b, au-3_smt.a, au-3_smt.d, au-3.1_smt, au-11_gdn, au-3_gdn, au-3.1_gdn", "answer_text": "Retain audit records for {{ insert: param, au-11_odp }} to provide support for after-the-fact investigations of incidents and to meet regulatory and organizational information retention requirements.

Ensure that audit records contain information that establishes the following: a. What type of event occurred; b. When the event occurred; c. Where the event occurred; d. Source of the event; e. Outcome of the event; and f. Identity of any individuals, subjects, or objects/entities associated with the event.

